insert into public.calendar_day_translations (
  calendar_day_id, language_code, title, saints, details, fasting_note, editorial_source
)
select
  d.id,
  'en',
  t.title,
  t.saints,
  t.details,
  t.fasting_note,
  t.editorial_source
from translations t
join public.calendar_days d
 on d.country_code = 'MD'
 and d.calendar_code = t.calendar_code
 and d.calendar_date = t.calendar_date::date
on conflict (calendar_day_id, language_code)
do update set
  title = excluded.title,
  saints = excluded.saints,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  editorial_source = excluded.editorial_source,
  updated_at = timezone('utc', now());

-- Validation guard: both Moldova calendars must have 365 English fallback rows.
do $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.calendar_day_translations tr
  join public.calendar_days d on d.id = tr.calendar_day_id
  where d.country_code = 'MD'
    and d.calendar_code in ('md-basarabia', 'md-chisinau')
    and d.calendar_date between '2026-01-01' and '2026-12-31'
    and tr.language_code = 'en';

  if v_count <> 730 then
    raise exception 'Invalid Moldova English fallback count: %', v_count;
  end if;
end $$;
